import { ReportLayout, COLORS, plain } from './pdf-layout.js';
import { enabledPhases } from './schema.js';
import { rankedThreats } from './validate.js';
import { insist } from './errors.js';
import { needsFullSourceRun } from './ingest.js';

const NOTICE =
  'Generated by AiTM using AI. This report was not authored, reviewed or endorsed by Oak Security.';
const LIMITATION =
  'This AI-assisted design-level analysis depends on the supplied evidence and expert review. It is not a code audit, penetration test, certification or warranty of completeness or accuracy. It does not imply that Oak Security authored or endorsed the assessment.';
const MODEL_GROUPS = [
  ['threatActors', 'Threat actors'],
  ['roles', 'Roles'],
  ['protectedAssets', 'Protected assets'],
  ['invariants', 'Critical invariants'],
  ['components', 'Components'],
];

// Quotations are deduplicated, not discarded: each claim links to the full quote
// and file/line reference in the evidence appendix, preserving assumptions inline.
function evidenceIndex(layout) {
  const entries = [];
  const keys = new Map();
  return {
    entries,
    render(item) {
      const refs = (item.evidence || []).map((e) => {
        const key = JSON.stringify([e.fileId, e.startLine, e.endLine, e.quote]);
        if (!keys.has(key)) {
          const id = `E${String(entries.length + 1).padStart(3, '0')}`;
          keys.set(key, id);
          entries.push({ ...e, id });
        }
        return keys.get(key);
      });
      if (refs.length) {
        layout.ensure(40);
        layout.text('Evidence references', { size: 9, bold: true, color: COLORS.muted, gap: 3 });
        for (let i = 0; i < refs.length; i += 8) {
          const row = refs.slice(i, i + 8);
          const y = layout.doc.y;
          row.forEach((id, n) => {
            layout.style(10, true, COLORS.magenta).text(id, layout.left + n * 60, y, {
              width: 54,
              lineBreak: false,
              goTo: `evidence-${id}`,
            });
          });
          layout.doc.y = y + 20;
        }
      }
      if (item.assumption)
        layout.field('Assumption / unverified', item.assumption, { color: COLORS.muted });
    },
  };
}

function cover(l, p, threats, reviewed) {
  l.page('Assessment');
  const d = l.doc;
  d.rect(0, 0, d.page.width, 130).fill(COLORS.ink);
  l.style(30, true, '#FFFFFF').text('AiTM', 48, 42, { lineBreak: false });
  l.style(10, false, COLORS.gold).text('TRACE / THREAT MODELLING', 48, 89, { lineBreak: false });
  // A small vector node mark; it stays crisp at print resolution.
  const nodes = [
    [457, 47],
    [532, 47],
    [457, 95],
    [532, 95],
    [495, 72],
  ];
  for (const [a, b] of [
    [0, 1],
    [0, 2],
    [1, 3],
    [2, 3],
    [0, 4],
    [4, 3],
  ])
    d.moveTo(...nodes[a])
      .lineTo(...nodes[b])
      .lineWidth(1)
      .stroke(COLORS.gold);
  for (const node of nodes) d.circle(...node, 4).fill(COLORS.gold);
  d.y = 178;
  l.text('SECURITY ASSESSMENT', { size: 10, bold: true, color: COLORS.magenta, gap: 20 });
  let titleSize = 38;
  while (l.height(p.name, l.width, titleSize, true) > 215 && titleSize > 24) titleSize -= 2;
  l.text(p.name, { size: titleSize, bold: true, gap: 14 });
  l.text('Threat model & mitigation plan', { size: 20, color: COLORS.muted, gap: 24 });
  l.text(reviewed ? 'Reviewed assessment' : 'DRAFT — expert review required', {
    size: 12,
    bold: true,
    color: COLORS.magenta,
    gap: 8,
  });
  l.text(`Generated ${p.artifacts.report.generatedAt}`, { size: 10, color: COLORS.muted, gap: 28 });
  const y = d.y;
  const metrics = [
    [threats.length, 'Ranked threats'],
    [p.artifacts.model.data.protectedAssets.length, 'Protected assets'],
    [p.artifacts.report.data.roadmap.length, 'Roadmap actions'],
  ];
  metrics.forEach(([value, label], i) => {
    const x = l.left + i * 171;
    d.roundedRect(x, y, 157, 88, 7).fill(COLORS.paper);
    l.style(27, true).text(String(value), x + 16, y + 13, { lineBreak: false });
    l.style(10, false, COLORS.muted).text(label, x + 16, y + 55, { lineBreak: false });
  });
  d.y = Math.max(y + 115, 670);
  l.text(NOTICE, { size: 10, color: COLORS.muted });
  l.text(
    'Findings first. Supporting sources, evidence and review records follow in the appendix.',
    { size: 10, color: COLORS.muted },
  );
}

function riskLandscape(l, threats) {
  l.section('Risk landscape');
  l.text(
    'Risk score = likelihood × impact, each assessed on a 1–5 scale. Scores prioritize review; they are not probabilities.',
    { color: COLORS.muted },
  );
  l.ensure(266);
  const d = l.doc,
    y = d.y + 10,
    x = 80,
    cell = 29;
  l.style(10, true).text('Likelihood', 48, y, { lineBreak: false });
  for (let likelihood = 5; likelihood >= 1; likelihood--) {
    const row = 5 - likelihood;
    l.style(9, false, COLORS.muted).text(String(likelihood), 58, y + 34 + row * cell, {
      lineBreak: false,
    });
    for (let impact = 1; impact <= 5; impact++) {
      const score = likelihood * impact;
      const color =
        score >= 20 ? COLORS.magenta : score >= 12 ? '#D881B4' : score >= 6 ? '#F2C9E3' : '#F5EAF1';
      const left = x + (impact - 1) * cell,
        top = y + 27 + row * cell;
      d.roundedRect(left, top, cell - 3, cell - 3, 3).fill(color);
      const count = threats.filter(
        (t) => t.likelihood === likelihood && t.impact === impact,
      ).length;
      if (count)
        l.style(11, true, score >= 20 ? '#FFFFFF' : COLORS.ink).text(String(count), left, top + 6, {
          width: cell - 3,
          align: 'center',
          lineBreak: false,
        });
    }
  }
  for (let i = 1; i <= 5; i++)
    l.style(9, false, COLORS.muted).text(String(i), x + (i - 1) * cell + 10, y + 179, {
      lineBreak: false,
    });
  l.style(10, true).text('Impact', x + 43, y + 202, { lineBreak: false });
  l.style(9, false, COLORS.muted).text('Cell count = threats; darker = higher score', 48, y + 227, {
    lineBreak: false,
  });
  const categories = [
    'Spoofing',
    'Tampering',
    'Repudiation',
    'Information disclosure',
    'Denial of service',
    'Elevation of privilege',
  ];
  l.style(10, true).text('STRIDE distribution', 282, y, { lineBreak: false });
  categories.forEach((category, i) => {
    const count = threats.filter((t) => t.category === category).length;
    const top = y + 26 + i * 35;
    l.style(9).text(category, 282, top, { width: 230, lineBreak: false });
    l.style(9, true).text(String(count), 520, top, { width: 27, align: 'right', lineBreak: false });
    d.roundedRect(282, top + 17, 265, 5, 2).fill(COLORS.paper);
    if (count)
      d.roundedRect(282, top + 17, Math.max(5, (265 * count) / threats.length), 5, 2).fill(
        COLORS.magenta,
      );
  });
  d.y = y + 263;
  l.heading('Threat directory');
  l.text('Select a threat ID to jump to its detailed assessment.', {
    size: 10,
    color: COLORS.muted,
  });
  if (!threats.length) l.text('No threats recorded. This does not establish absence of risk.');
  for (const t of threats)
    l.row(`${t.id}\n${t.likelihood * t.impact} / 25`, `${t.title}\n${t.category}`, {
      destination: `threat-${t.id}`,
      labelWidth: 95,
      size: 11,
    });
}

function threatDetails(l, threats, evidence) {
  l.section('Ranked STRIDE threats');
  l.text(
    'Each assessment connects a scenario to the affected model objects, existing controls and proposed mitigations.',
    { color: COLORS.muted },
  );
  for (const [index, t] of threats.entries()) {
    if (index) l.page('Ranked STRIDE threats');
    l.anchor(`threat-${t.id}`);
    l.text(`${t.id} / ${t.category}`, { size: 10, bold: true, color: COLORS.magenta, gap: 10 });
    l.heading(t.title, { size: 23, keep: 90 });
    l.ensure(76);
    const y = l.doc.y,
      score = t.likelihood * t.impact;
    l.doc.roundedRect(l.left, y, l.width, 65, 6).fill(COLORS.paper);
    l.style(23, true, COLORS.magenta).text(`${score} / 25`, 62, y + 10, { lineBreak: false });
    l.style(10).text(`Likelihood ${t.likelihood}/5   ×   Impact ${t.impact}/5`, 196, y + 12, {
      lineBreak: false,
    });
    l.style(9, false, COLORS.muted).text(`Confidence: ${t.confidence}`, 196, y + 34, {
      lineBreak: false,
    });
    l.doc.roundedRect(62, y + 45, 112, 5, 2).fill(COLORS.line);
    l.doc.roundedRect(62, y + 45, (112 * score) / 25, 5, 2).fill(COLORS.magenta);
    l.doc.y = y + 85;
    l.field('Scenario', t.scenario);
    l.field('Ranking rationale', t.rationale);
    for (const [key, label] of [
      ['feasibility', 'Feasibility'],
      ['incentives', 'Incentives'],
      ['blastRadius', 'Blast radius'],
      ['timeSensitivity', 'Time sensitivity'],
    ])
      l.field(label, t[key]);
    l.heading('Existing controls', { size: 13 });
    l.bullets(t.existingControls);
    l.heading('Mitigations', { size: 13 });
    l.bullets(t.mitigations);
    l.field(
      'Targets / actors / protected assets / invariants',
      [
        `Targets: ${t.targetIds.join(', ') || 'None recorded'}`,
        `Actors: ${t.actorIds.join(', ') || 'None recorded'}`,
        `Assets: ${t.assetIds.join(', ') || 'None recorded'}`,
        `Invariants: ${t.invariantIds.join(', ') || 'None recorded'}`,
      ].join('\n'),
      { size: 10 },
    );
    evidence.render(t);
  }
}

function treeDiagram(l, tree) {
  l.heading(tree.goal, { size: 17 });
  l.text(
    `${tree.threatId} / AND requires all branches; OR requires one. LEAF is an individual action.`,
    { size: 10, color: COLORS.muted },
  );
  const placed = new Map();
  function walk(parentId, depth) {
    for (const node of tree.nodes.filter((n) => n.parentId === parentId)) {
      const indent = Math.min(depth, 6) * 22;
      const x = l.left + indent,
        width = l.width - indent;
      const meta = `${node.id} / ${node.operator}${node.speculative ? ' / SPECULATIVE' : ''}`;
      const parent = parentId ? `Continued from ${parentId}` : '';
      const baseHeight =
        l.height(meta, width - 28, 9, true) + l.height(node.label, width - 28, 11, true) + 23;
      const prev = placed.get(parentId);
      let continued = prev && (prev.page !== l.pages.length || depth > 6);
      let height = baseHeight + (continued ? l.height(parent, width - 28, 9) + 4 : 0);
      if (l.doc.y + height + 8 > l.bottom) {
        l.page();
        continued = Boolean(parentId);
        height = baseHeight + (continued ? l.height(parent, width - 28, 9) + 4 : 0);
      }
      const y = l.doc.y,
        d = l.doc;
      if (prev && prev.page === l.pages.length && depth <= 6) {
        d.moveTo(x - 10, prev.bottom)
          .lineTo(x - 10, y + 15)
          .lineTo(x, y + 15)
          .lineWidth(1)
          .stroke(COLORS.magenta);
      }
      d.roundedRect(x, y, width, height, 6).fill(node.speculative ? COLORS.pale : COLORS.paper);
      d.rect(x, y + 8, 3, height - 16).fill(
        node.operator === 'LEAF' ? COLORS.gold : COLORS.magenta,
      );
      let top = y + 12;
      l.style(9, true, COLORS.magenta).text(meta, x + 14, top, { width: width - 28, lineGap: 4 });
      top = d.y + 4;
      l.style(11, true).text(plain(node.label), x + 14, top, { width: width - 28, lineGap: 4 });
      if (continued)
        l.style(9, false, COLORS.muted).text(parent, x + 14, d.y + 5, {
          width: width - 28,
          lineGap: 4,
        });
      placed.set(node.id, { page: l.pages.length, bottom: y + height });
      d.y = y + height + 8;
      walk(node.id, depth + 1);
    }
  }
  walk(null, 0);
}

function attacks(l, p, evidence) {
  l.section('Attack trees');
  for (const [i, tree] of p.artifacts.trees.data.trees.entries()) {
    if (i) l.page('Attack trees');
    treeDiagram(l, tree);
    l.gap(10);
    l.heading('Node prerequisites & defenses');
    for (const node of tree.nodes) {
      l.heading(`${node.id} / ${node.label}`, { size: 13 });
      l.field('Prerequisites', node.prerequisites.join('\n') || 'None recorded.');
      l.field('Mitigations', node.mitigations.join('\n') || 'See the child nodes.');
      evidence.render(node);
      l.gap(7);
    }
  }
  if (p.artifacts.trees.data.omitted.length) {
    l.heading('Documented tree omissions');
    l.bullets(p.artifacts.trees.data.omitted.map((t) => `${t.threatId}: ${t.reason}`));
  }
}

function coordination(l, p, evidence) {
  l.section('Collusion & coordination');
  const c = p.artifacts.coordination.data;
  for (const item of c.scenarios) {
    l.heading(`${item.id} / ${item.title}`);
    for (const [label, value] of [
      ['Actors / roles', item.actorIds.join(', ')],
      ['Protected assets', item.assetIds.join(', ')],
      ['Threshold', item.threshold],
      ['Incentive', item.incentive],
      ['Shared dependencies', item.sharedDependencies.join('\n')],
      ['Consequence', item.consequence],
    ])
      l.field(label, value);
    l.heading('Mitigations', { size: 13 });
    l.bullets(item.mitigations);
    evidence.render(item);
    l.gap(16);
  }
  l.heading('Coordination assumptions');
  l.bullets(c.assumptions);
}

function roadmap(l, p, enabled) {
  l.section('Mitigation roadmap');
  const report = p.artifacts.report.data;
  const horizons = ['immediate', '30 days', '60 days', '90 days'];
  const y = l.doc.y;
  horizons.forEach((priority, i) => {
    const x = l.left + i * 127;
    const count = report.roadmap.filter((r) => r.priority === priority).length;
    l.doc.roundedRect(x, y, 118, 76, 6).fill(i === 0 ? COLORS.pale : COLORS.paper);
    l.style(10, true, COLORS.magenta).text(
      priority === 'immediate' ? 'Immediate' : priority,
      x + 12,
      y + 12,
      { lineBreak: false },
    );
    l.style(24, true).text(String(count), x + 12, y + 32, { lineBreak: false });
    l.style(9, false, COLORS.muted).text('actions', x + 46, y + 46, { lineBreak: false });
  });
  l.doc.y = y + 102;
  for (const priority of horizons) {
    const items = report.roadmap.filter((r) => r.priority === priority);
    if (!items.length) continue;
    l.heading(priority === 'immediate' ? 'Immediate' : `Within ${priority}`, { size: 20 });
    for (const r of items) {
      l.heading(`${r.id} / ${r.owner}`, { size: 13 });
      l.text(r.action);
      l.field('Priority', r.priority, { size: 10 });
      l.field('Verification / acceptance', r.verification);
      l.field('Linked findings & model objects', r.linkedIds.join(', '), { size: 10 });
      l.rule();
      l.gap(20);
    }
  }
  l.heading('Residual risks');
  l.bullets(report.residualRisks);
  l.heading('Open assumptions & questions');
  l.bullets([
    ...p.artifacts.model.data.openQuestions,
    ...p.artifacts.stride.data.openQuestions,
    ...(enabled.has('coordination') ? p.artifacts.coordination?.data.openQuestions || [] : []),
    ...report.openQuestions,
  ]);
  l.heading('Next steps');
  l.bullets(report.nextSteps);
}

function systemModel(l, p, evidence) {
  l.section('System model');
  const m = p.artifacts.model.data;
  l.text(m.overview);
  for (const [key, title] of MODEL_GROUPS) {
    l.heading(title, { size: 20 });
    if (!m[key].length) l.text('None recorded.', { color: COLORS.muted });
    for (const item of m[key]) {
      l.heading(`${item.id} / ${item.name}`, { size: 13 });
      l.text(item.description);
      evidence.render(item);
      l.rule();
      l.gap(14);
    }
  }
  l.heading('Edges & trust boundaries', { size: 20 });
  const names = new Map(MODEL_GROUPS.flatMap(([key]) => m[key].map((v) => [v.id, v.name])));
  for (const edge of m.edges) {
    l.heading(`${edge.id} / ${edge.name}`, { size: 13 });
    const from = `${edge.from}\n${names.get(edge.from) || ''}`;
    const to = `${edge.to}\n${names.get(edge.to) || ''}`;
    const boxWidth = 223,
      inner = boxWidth - 24;
    const height = Math.max(l.height(from, inner, 10), l.height(to, inner, 10)) + 24;
    l.ensure(height + 15);
    const y = l.doc.y;
    for (const [x, label] of [
      [48, from],
      [324.28, to],
    ]) {
      l.doc.roundedRect(x, y, boxWidth, height, 5).fill(COLORS.paper);
      l.style(10).text(plain(label), x + 12, y + 12, { width: inner, lineGap: 4 });
    }
    const middle = y + height / 2;
    l.doc.moveTo(279, middle).lineTo(315, middle).lineWidth(1.4).stroke(COLORS.magenta);
    l.doc
      .moveTo(309, middle - 4)
      .lineTo(315, middle)
      .lineTo(309, middle + 4)
      .stroke(COLORS.magenta);
    l.doc.y = y + height + 12;
    l.field(`${edge.kind} / trust boundary`, edge.boundary);
    l.text(edge.description);
    evidence.render(edge);
    l.gap(15);
  }
  l.heading('Coverage', { size: 20 });
  l.text(
    'Recorded threat coverage for each model object. Review the rationale even when no threats are listed.',
    { color: COLORS.muted },
  );
  for (const row of p.artifacts.stride.data.coverage) {
    l.heading(row.objectId, { size: 12 });
    l.field('Threats', row.threatIds.join(', ') || 'None recorded.', { size: 10 });
    l.text(row.explanation);
    l.rule();
    l.gap(14);
  }
}

function appendix(l, p, phases, evidence) {
  l.section('Evidence & sources');
  l.text(
    'Evidence IDs link claims to complete quotations. An evidence reference records a source location; assumptions and unresolved review notes remain explicitly unverified.',
    { color: COLORS.muted },
  );
  const notes = phases.flatMap((phase) =>
    (p.artifacts[phase.id]?.reviewNotes || []).map(
      (note) => `${phase.title} — ${note.claim}: ${note.note}`,
    ),
  );
  if (notes.length) {
    l.heading('Evidence review required');
    l.bullets(notes);
  }
  l.heading('Evidence index', { size: 20 });
  const files = new Map(
    p.sources.flatMap((source) =>
      source.files.map((file) => [file.id, `${source.label}/${file.path}`]),
    ),
  );
  for (const e of evidence.entries) {
    l.heading(`${e.id} / lines ${e.startLine}–${e.endLine}`, { size: 12, id: `evidence-${e.id}` });
    l.text(files.get(e.fileId) || e.fileId, { size: 10, bold: true });
    l.text(`File ID: ${e.fileId}`, { size: 9, color: COLORS.muted });
    l.text(`“${e.quote}”`, { size: 10.5, indent: 14, literal: true });
    l.rule();
    l.gap(14);
  }
  if (!evidence.entries.length)
    l.text('No source quotations recorded. Review assumptions before relying on this assessment.');
  l.heading('Source inventory', { size: 20 });
  for (const s of p.sources) {
    l.heading(s.label, { size: 13 });
    l.text(`${s.kind} / ${s.files.length} files`, { size: 10 });
    l.field('Revision / SHA-256', s.commit || s.hash, { size: 9.5 });
  }
  l.heading('Evidence files', { size: 20 });
  for (const s of p.sources)
    for (const f of s.files) {
      // Full paths and hashes remain selectable and wrap without ellipsis.
      l.ensure(90);
      l.text(`${s.label}/${f.path}`, { size: 10, bold: true, gap: 3 });
      l.text(`File ID: ${f.id}\nSHA-256: ${f.hash}`, { size: 9, color: COLORS.muted, gap: 10 });
      l.rule();
      l.gap(12);
    }
}

export async function pdfReport(project) {
  insist(project.artifacts.report, 'Generate the report phase first.', 409, 'report_missing');
  const l = new ReportLayout(project),
    phases = enabledPhases(project),
    enabled = new Set(phases.map((p) => p.id));
  const threats = rankedThreats(project),
    evidence = evidenceIndex(l);
  const reviewed = phases
    .filter((p) => p.gate)
    .every((p) => project.artifacts[p.id]?.status === 'approved');
  cover(l, project, threats, reviewed);
  l.page('Contents');
  const contentsPage = l.pages.length - 1;
  l.section('Executive summary');
  if (needsFullSourceRun(project))
    l.text(
      'This saved analysis used incomplete source text. Run the full pipeline again to process the complete source and rebuild the assessment.',
      { bold: true, color: COLORS.magenta },
    );
  l.text(project.artifacts.report.data.executiveSummary, { size: 12 });
  l.gap(12);
  l.heading('Scope');
  l.text(project.scope);
  l.gap(12);
  l.heading('Reading this assessment');
  l.bullets([
    'Start with the risk landscape and ranked findings, then use the roadmap to plan verification and mitigation.',
    'Attack trees show AND / OR dependencies. Speculative nodes and assumptions need evidence and human review.',
    'Supporting model objects, source hashes and full evidence quotations are retained in the appendix.',
  ]);
  riskLandscape(l, threats);
  threatDetails(l, threats, evidence);
  if (enabled.has('trees') && project.artifacts.trees) attacks(l, project, evidence);
  if (enabled.has('coordination') && project.artifacts.coordination)
    coordination(l, project, evidence);
  roadmap(l, project, enabled);
  systemModel(l, project, evidence);
  appendix(l, project, phases, evidence);
  l.section('Review record');
  l.text(
    reviewed
      ? 'All enabled review gates have been approved.'
      : 'DRAFT — expert review required. Generation does not constitute approval.',
    { bold: true, color: COLORS.magenta },
  );
  for (const phase of phases) {
    const a = project.artifacts[phase.id];
    l.row(
      phase.title,
      `Status: ${a?.status || 'missing'}\n${a?.review ? `${a.review.reviewer || 'Approved'} / ${a.review.at}` : 'Not approved'}`,
    );
    if (a?.review?.notes) l.field('Review notes', a.review.notes);
  }
  l.gap(20);
  l.heading('Notice');
  l.text(NOTICE);
  l.text(LIMITATION, { color: COLORS.muted });
  l.doc.switchToPage(contentsPage);
  l.doc.y = 88;
  l.heading('Contents', { size: 30 });
  l.text('Select a section to navigate. PDF bookmarks provide the same shortcuts.', {
    size: 10,
    color: COLORS.muted,
  });
  l.gap(20);
  for (const entry of l.contents)
    l.row(`${entry.number} / ${entry.page}`, entry.title, {
      destination: entry.id,
      size: 12,
      labelWidth: 75,
    });
  return l.finish();
}
